input_sequence = ("")

def letter_to_number(letter):
    """Convert a letter to its corresponding position (a=1, ..., z=26)."""
    return ord(letter) - ord('a') + 1

def number_to_letter(number):
    """Convert a number back to a letter (1=a, ..., 26=z)."""
    return chr((number - 1) % 26 + ord('a'))

letters = [char for char in input_sequence if char.isalpha()]
numbers = [int(char) for char in input_sequence if char.isdigit()]

length = min(len(letters), len(numbers))
letters = letters[:length]
numbers = numbers[:length]

result = [number_to_letter(letter_to_number(letters[i]) * numbers[i]) for i in range(length)]

output_text = ''.join(result)
print(output_text)

